    &lt;tr&gt;&lt;td&gt;&lt;b&gt;Inquisitions&lt;/b&gt;&lt;/td&gt;
        &lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#COLERE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Col&#232;re&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#HERESIE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;H&#233;r&#233;sie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#TACTIQUE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Tactique&lt;/a&gt;&lt;/td&gt;
